"""autoedit engine farm entry (farm contract v1; generated by regen_engine.py). Wraps build.py + audio.py.
python -I -X utf8 build/farm_entry.py plan | chunk F0 F1 OUT.ts [--framemd5 PATH] | audio OUT.wav
Paths come from this file's folder, so it runs from the production or from the farm part copy."""
import os, subprocess, sys
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import numpy as np
import farm_contract as fc
import build as B
import audio as AU
import mapclip

FPS, W, H = 30, 1920, 1080
ENC = ['-c:v', 'libx264', '-preset', 'medium', '-crf', '18', '-pix_fmt', 'yuv420p']
SRC = lambda s: f'sources/{s}.mp4'


def shot_files(s, T, depth=0):
    """Big media one shot reads (paths relative to the part dir). Small assets (pages, map tiles, fonts,
    music, SFX; all <= 25 MB) come in the part's pack, so only pages are listed besides the sources."""
    k, out = s['kind'], set()
    if k in ('ff', 'still'):
        out.add(SRC(s['src']))
        if k == 'ff' and s.get('xfade') and s['idx'] > 0 and depth == 0: out |= set(shot_files(T[s['idx'] - 1], T, 1))
    elif k == 'card': out.add(SRC(s['plate']['src']))
    elif k == 'list': out.add(SRC(s['plate']['src']))
    elif k == 'page': out.add(f"assets/pages/{s['page']}_page.png")
    elif k == 'map': out.add(mapclip.clip_rel(s))                     # PC map clip (may be > 25 MB: not in the pack)
    elif k == 'end' and depth == 0: out |= set(shot_files(T[s['idx'] - 1], T, 1))
    return sorted(out)


def plan():
    T = B.shots(); f, st = 0, []
    for s in T:
        if s['f0'] != f: raise ValueError(f"shot {s['idx']} f0={s['f0']} != {f}")
        st.append(f); f += s['nf']
    if (B.FPS, B.W, B.H) != (FPS, W, H): raise ValueError('build.py fps/size changed')
    return dict(fps=FPS, w=W, h=H, frames=f, borders=st,
                shots=[dict(f0=a, f1=a + s['nf'], files=shot_files(s, T)) for a, s in zip(st, T)])


def chunk(f0, f1, out, md5_path=None):
    T = B.shots()
    md5 = fc.FrameMD5(md5_path); n = 0
    p = subprocess.Popen(['ffmpeg', '-v', 'error', '-y', '-f', 'rawvideo', '-pix_fmt', 'rgb24', '-s', f'{W}x{H}', '-r', str(FPS),
                          '-i', '-', *fc.chunk_enc(ENC, f0, FPS), out], stdin=subprocess.PIPE)
    try:
        for s in (s for s in T if f0 <= s['f0'] < f1):
            k = 0
            for a in B.render_range(s, 0, s['nf']):
                if a.shape != (H, W, 3) or a.dtype != np.uint8: raise SystemExit(f"shot {s['idx']}: frame {a.shape} {a.dtype}")
                buf = np.ascontiguousarray(a).tobytes(); md5.add(buf); p.stdin.write(buf); k += 1
            if k != s['nf']: raise SystemExit(f"shot {s['idx']}: {k} frames, want {s['nf']}")
            n += k
    finally:
        p.stdin.close(); rc = p.wait(); md5.close()
    if rc or n != f1 - f0: raise SystemExit(f'chunk {f0}..{f1}: ffmpeg rc={rc}, frames {n}')
    print('chunk frames', n, file=sys.stderr)


def audio(out):
    T = B.shots(); frames = sum(s['nf'] for s in T); n = frames * AU.SPF
    pre = out + '.premix.wav'
    AU.premix(pre, T); AU.master(pre, out)
    x = AU.load(out); os.remove(pre)
    if len(x) != n:                                                        # exact length: frames / 30 s at 48 kHz
        print(f'audio: fix length {len(x)} -> {n} samples', file=sys.stderr)
        x = x[:n] if len(x) >= n else np.vstack([x, np.zeros((n - len(x), x.shape[1]), np.float32)])
        subprocess.run(['ffmpeg', '-v', 'error', '-y', '-f', 'f32le', '-ar', str(AU.SR), '-ac', str(x.shape[1]), '-i', '-',
                        '-c:a', 'pcm_f32le', out], input=np.ascontiguousarray(x, np.float32).tobytes(), check=True)
    print('audio samples', n, 'frames', frames, file=sys.stderr)


if __name__ == '__main__':
    sys.exit(fc.main(sys.argv[1:], plan, chunk, audio))
